        for(int i0=0; i0<8; i0++) begin
            if(rd_mux_addr == 12'h100 + (12)'(i0) * 12'h20) begin
                readback_data_var[0] = field_storage.cs[i0].cfg.cpol.value;
                readback_data_var[1] = field_storage.cs[i0].cfg.cpha.value;
                readback_data_var[2] = field_storage.cs[i0].cfg.lsb_first.value;
                readback_data_var[3] = field_storage.cs[i0].cfg.loopback.value;
            end
            if(rd_mux_addr == 12'h104 + (12)'(i0) * 12'h20) begin
                readback_data_var[15:0] = field_storage.cs[i0].clkdiv.value.value;
            end
            if(rd_mux_addr == 12'h108 + (12)'(i0) * 12'h20) begin
                readback_data_var[15:0] = field_storage.cs[i0].timing0.setup.value;
                readback_data_var[31:16] = field_storage.cs[i0].timing0.hold_time.value;
            end
            if(rd_mux_addr == 12'h10c + (12)'(i0) * 12'h20) begin
                readback_data_var[15:0] = field_storage.cs[i0].timing1.idle.value;
                readback_data_var[31:16] = field_storage.cs[i0].timing1.frame_gap.value;
            end
            if(rd_mux_addr == 12'h110 + (12)'(i0) * 12'h20) begin
                readback_data_var[31:0] = field_storage.cs[i0].dummy.value.value;
            end
        end
        readback_data = readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = decoded_err;
    end

    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
